CREATE VIEW [dbo].[CCassaSconti2] AS select data, 'Corrispettivi Società'  as descrizione, sum(incassonetto) as Entrate, 0 as uscite from incassi group by data Union select data, 'Preu incassato'  as descrizione, sum(tasse) as Entrate, 0 as uscite from incassi where tasse <> 0  group by data Union select data, 'AAMS incassato'  as descrizione, sum(AAMS) as Entrate, 0 as uscite  from incassi  where aams <> 0  group by data Union select data, 'Rete incassata'  as descrizione, sum(RETE) as Entrate, 0 as uscite from incassi where rete <> 0  group by data Union select data, 'Sospesi'  as descrizione, 0 as Entrate, sum(abs(importo))  as uscite from sospesirientri  where  sospesirientri.importo < 0   group by data Union select data, 'Recuperi'  as descrizione, sum(importo) as Entrate, 0  as uscite  from sospesirientri where  sospesirientri.importo >  0   group by data Union select datada as data, 'Cariche Iniziali'  as descrizione, 0 as Entrate, sum(totsocieta) as uscite  from hopper where totsocieta <> 0 and not totsocieta  is null group by datada Union select dataa as data, 'Cariche Finali'  as descrizione, sum(totsocfin) as Entrate, 0  as uscite  from hopper where totsocfin <> 0 and not totsocfin  is null group by dataa Union select data, 'Refill Recuperati' as Descrizione, sum(refillsocieta) as Entrate, 0 as uscite from refillhopper where refillhopper.refillsocieta > 0  group by data Union select data, 'Refill Generati' as Descrizione, 0 as Entrate, sum(abs(refillsocieta)) as uscite from refillhopper where  refillhopper.refillsocieta < 0  group by data Union select data, 'Uscite Cassa' as Descrizione, 0 as Entrate, sum(uscita) as Uscite from cOperazione where Uscita>0 and ParModalita=1 group by data Union select data, 'Acconti Utilizzati'  as descrizione, 0 as Entrate, sum(abs(importo))  as uscite from acconti  where  acconti.importo < 0 group by data  Union select data, 'Acconti Prelevati'  as descrizione, sum(importo) as Entrate, 0  as uscite  from acconti where  acconti.importo >  0 group by data
GO
